True def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}
    if not colors:
        return out
    foreground = next(iter(colors))
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] == foreground and row[c + 2] == foreground:
                out[r][c + 1] = 2
    return out
